    </div></section>

    <div class="is-savebar mb-3"><span class="is-save-note"><i class="fa-solid fa-shield-halved me-2 text-success"></i>Changes are audit logged and apply after saving.</span><button class="btn btn-is-primary px-4" type="submit"><i class="fa-solid fa-floppy-disk me-2"></i>Save Issuance Settings</button></div>
  </form>

  <section class="is-section" id="indigency-officials"><div class="is-section-head"><span class="is-section-icon"><i class="fa-solid fa-user-tie"></i></span><div><h2 class="is-section-title">Certificate of Indigency — Government Officials</h2><p class="is-section-copy">Manage the officials shown in the “To be submitted to” dropdown. Changes are immediately available on the resident request form.</p></div></div><div class="is-section-body">
    <h3 class="h6 fw-bold mb-3">Add government official</h3>
    <form class="is-official-form mb-4" id="indigencyOfficialForm" method="post" action="<?= htmlspecialchars($documentSettingsActionUrl) ?>"><?= csrfTokenField() ?><input type="hidden" name="action" value="save_indigency_government_official"><input type="hidden" name="government_official_id" id="indigencyOfficialId" value="0">
      <div><label class="form-label small fw-semibold">Name</label><input class="form-control" id="indigencyOfficialName" name="official_name" required placeholder="e.g. Hon. Juan Dela Cruz"></div>
      <div><label class="form-label small fw-semibold">Position</label><input class="form-control" id="indigencyOfficialPosition" name="position_name" required placeholder="e.g. Municipal Mayor"></div>
      <div><label class="form-label small fw-semibold">Office / Jurisdiction</label><input class="form-control" id="indigencyOfficialLocation" name="jurisdiction_location" required placeholder="e.g. Rodriguez, Rizal"></div>
      <div><label class="form-label small fw-semibold">Office group</label><select class="form-select" id="indigencyOfficialGroup" name="group_key" required><option value="president">President</option><option value="vice_president">Vice President</option><option value="senate">Senate</option><option value="rizal_officials">Rizal Officials</option><option value="municipal_officials" selected>Rodriguez Municipal Officials</option></select></div>
      <div><label class="form-label small fw-semibold">Order</label><input class="form-control" id="indigencyOfficialOrder" type="number" min="0" max="9999" name="display_order" value="0"></div>
      <div class="is-official-submit"><div class="form-check mb-2 d-none" id="indigencyOfficialActiveWrap"><input class="form-check-input" type="checkbox" name="is_active" id="indigencyOfficialActive" checked><label class="form-check-label small" for="indigencyOfficialActive">Active</label></div><button class="btn btn-is-primary w-100" id="indigencyOfficialSubmit"><i class="fa-solid fa-plus me-2"></i>Add</button><button class="btn btn-outline-secondary w-100 mt-2 d-none" type="button" id="indigencyOfficialCancel">Cancel</button></div>
    </form>
    <div class="table-responsive"><table class="table table-hover align-middle is-official-table mb-0"><thead><tr><th>Name</th><th>Position</th><th>Office / Jurisdiction</th><th>Group</th><th>Order</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody>
      <?php if ($governmentOfficialRows === []): ?><tr><td colspan="7" class="text-center text-muted py-4">No government officials configured.</td></tr><?php endif; ?>
      <?php foreach($governmentOfficialRows as $official): $officialId=(int)$official['government_official_id']; ?><tr><td><span class="is-official-name"><?= htmlspecialchars((string)$official['official_name']) ?></span></td><td><?= htmlspecialchars((string)$official['position_name']) ?></td><td><?= htmlspecialchars((string)$official['jurisdiction_location']) ?></td><td><span class="is-official-meta"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$official['group_key']))) ?></span></td><td><?= (int)$official['display_order'] ?></td><td><?= !empty($official['is_active'])?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Inactive</span>' ?></td><td><div class="is-official-actions"><button type="button" class="btn btn-sm btn-outline-primary" data-official-edit data-id="<?= $officialId ?>" data-name="<?= htmlspecialchars((string)$official['official_name'],ENT_QUOTES,'UTF-8') ?>" data-position="<?= htmlspecialchars((string)$official['position_name'],ENT_QUOTES,'UTF-8') ?>" data-location="<?= htmlspecialchars((string)$official['jurisdiction_location'],ENT_QUOTES,'UTF-8') ?>" data-group="<?= htmlspecialchars((string)$official['group_key'],ENT_QUOTES,'UTF-8') ?>" data-order="<?= (int)$official['display_order'] ?>" data-active="<?= !empty($official['is_active'])?'1':'0' ?>"><i class="fa-solid fa-pen"></i></button><form method="post" action="<?= htmlspecialchars($documentSettingsActionUrl) ?>" onsubmit="return confirm('Delete this government official from the dropdown?');"><?= csrfTokenField() ?><input type="hidden" name="action" value="delete_indigency_government_official"><input type="hidden" name="government_official_id" value="<?= $officialId ?>"><button class="btn btn-sm btn-outline-danger" aria-label="Delete"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endforeach; ?>
    </tbody></table></div>
