</div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>
(() => {
  const form = document.getElementById('indigencyOfficialForm');
  if (!form) return;
  const fields = {
    id: document.getElementById('indigencyOfficialId'), name: document.getElementById('indigencyOfficialName'),
    position: document.getElementById('indigencyOfficialPosition'), location: document.getElementById('indigencyOfficialLocation'),
    group: document.getElementById('indigencyOfficialGroup'), order: document.getElementById('indigencyOfficialOrder'),
    active: document.getElementById('indigencyOfficialActive')
  };
  const submit = document.getElementById('indigencyOfficialSubmit');
  const cancel = document.getElementById('indigencyOfficialCancel');
  const activeWrap = document.getElementById('indigencyOfficialActiveWrap');
  const reset = () => { form.reset(); fields.id.value='0'; fields.group.value='municipal_officials'; fields.order.value='0'; fields.active.checked=true; activeWrap.classList.add('d-none'); cancel.classList.add('d-none'); submit.innerHTML='<i class="fa-solid fa-plus me-2"></i>Add'; };
  document.querySelectorAll('[data-official-edit]').forEach((button) => button.addEventListener('click', () => {
    fields.id.value=button.dataset.id||'0'; fields.name.value=button.dataset.name||''; fields.position.value=button.dataset.position||''; fields.location.value=button.dataset.location||''; fields.group.value=button.dataset.group||'municipal_officials'; fields.order.value=button.dataset.order||'0'; fields.active.checked=button.dataset.active==='1'; activeWrap.classList.remove('d-none'); cancel.classList.remove('d-none'); submit.innerHTML='<i class="fa-solid fa-floppy-disk me-2"></i>Update'; form.scrollIntoView({behavior:'smooth',block:'center'}); fields.name.focus();
  }));
  cancel.addEventListener('click', reset);
})();
</script></body></html>
